\newcommand{\myCycinder}[7]{
	\begin{scope}[scale=#6]
		\coordinate (O) at (0,0,0);
		\coordinate (A) at (#1,0,0);
		\coordinate (A') at (#1+#7,#3,0);
		\coordinate (B) at (-#1,0,0);
		\coordinate (B') at (-#1+#7,#3,0);
		\coordinate (S) at (#7,#3,0);

		% Base/Top
		\draw[draw=none, fill=#4!25, fill opacity=#5] (O) circle (#1 and #2);
		\draw[draw=none, fill=#4!15, fill opacity=1] (S) circle (#1 and #2);

		% Circ		
		\fill[draw=none, fill=#4!15, fill opacity=#5] (B') -- (B) arc (180:360:#1 and #2) -- (A') -- cycle;		


		% Edges
			% Base
			\draw[thin, color=#4, dashed, opacity=0.75] (O)+(#1,0,0) arc (0:180:#1 and #2);
			\draw[very thick, color=#4] (B) arc (180:360:#1 and #2);

			% Gen.
			\draw[very thick, color=#4](A)--(A');
			\draw[very thick, color=#4](B)--(B');

			% Top
			\draw[very thick, color=#4] (O)+(#1+#7,#3,0) arc (0:180:#1 and #2);
			\draw[very thick, color=#4] (B') arc (180:360:#1 and #2);

		\tkzDrawPoints[size=5, color=none, fill=#4](O,S);			
%		\tkzLabelPoints[below right](O);
%		\tkzLabelPoints[above](S);
%		\tkzLabelPoints[below right](A);
%		\tkzLabelPoints[below left](B);

	\end{scope}
}

